export type RunState = "active" | "succeeded" | "failed" | "cancelled";
export type UnitState = "ready" | "working" | "waiting" | "satisfied" | "failed" | "cancelled";
export type WorkOrderState = "available" | "started" | "completed" | "abandoned";
